'''Message dispatcher: pull from a Mailbox and deliver to subscribers.'''

from queue_box import Mailbox

MAX_RETRIES = 3


class Dispatcher:
    '''Deliver mailbox messages to per-channel subscriber handlers.'''

    def __init__(self) -> None:
        self._box = Mailbox()
        self._subscribers = {}
        self.dead_letters: list = []

    def publish(self, channel: str, payload: str) -> None:
        self._box.push((channel, payload))

    def subscribe(self, channel: str, handler) -> None:
        self._subscribers[channel] = handler

    def pending(self) -> int:
        return len(self._box)

    def dispatch_all(self) -> int:
        '''Deliver pending messages, retrying failed ones.

        Ensures strict FIFO ordering: if a message fails to deliver after
        MAX_RETRIES attempts, it and all subsequent messages remain in the
        mailbox with the failed message at the head.  Messages for channels
        without subscribers are moved to dead_letters immediately.
        '''
        delivered = 0

        # Drain the mailbox into a local list to preserve order.
        messages = []
        while len(self._box) > 0:
            messages.append(self._box.pop())

        i = 0
        while i < len(messages):
            channel, payload = messages[i]
            handler = self._subscribers.get(channel)
            if handler is None:
                # No subscriber: dead-letter immediately.
                self.dead_letters.append((channel, payload))
                i += 1
                continue

            # Retry up to MAX_RETRIES times.
            success = False
            for _ in range(MAX_RETRIES):
                try:
                    handler(payload)
                    success = True
                    break
                except Exception:
                    continue

            if success:
                delivered += 1
                i += 1
            else:
                # Failed after MAX_RETRIES: put this message and all
                # following messages back into the mailbox in original order.
                # The failed message becomes the new head.
                for msg in messages[i:]:
                    self._box.push(msg)
                break

        return delivered

