import unittest

from dispatcher import Dispatcher


class TestFifoUnderRetryContract(unittest.TestCase):
    def test_failed_message_keeps_head_of_line(self):
        """A failed message keeps its FIFO head position; later messages
        must not overtake it (strict ordering under retry)."""
        d = Dispatcher()
        received = []
        state = {"fail": True}

        def flaky(p):
            if p == "a" and state["fail"]:
                state["fail"] = False
                raise RuntimeError("transient")
            received.append(p)

        d.subscribe("orders", flaky)
        for p in ["a", "b", "c"]:
            d.publish("orders", p)
        d.dispatch_all()
        self.assertEqual(received, ["a", "b", "c"])

    def test_failed_message_is_not_lost(self):
        d = Dispatcher()
        received = []
        state = {"fail": True}

        def flaky(p):
            if state["fail"]:
                state["fail"] = False
                raise RuntimeError("transient")
            received.append(p)

        d.subscribe("orders", flaky)
        d.publish("orders", "only")
        d.dispatch_all()
        d.dispatch_all()
        self.assertEqual(received, ["only"])
        self.assertEqual(d.pending(), 0)


if __name__ == "__main__":
    unittest.main()
